class Solution {
public:
    std::vector<long long> maximumSegmentSum(std::vector<int>& nums, std::vector<int>& removeQueries) {
        int n = nums.size();
        std::vector<int> parent(n);
        std::iota(parent.begin(), parent.end(), 0);
        std::vector<long long> seg_sum(n, 0);
        std::vector<bool> active(n, false);
        auto find = [&](auto& self, int i) -> int {
            return parent[i] == i ? i : (parent[i] = self(self, parent[i]));
        };
        auto unite = [&](int i, int j) {
            int ri = find(find, i), rj = find(find, j);
            if (ri != rj) {
                parent[ri] = rj;
                seg_sum[rj] += seg_sum[ri];
            }
        };
        std::vector<long long> ans(n, 0);
        long long cur_max = 0;
        for (int q = n - 1; q >= 0; --q) {
            ans[q] = cur_max;
            int i = removeQueries[q];
            active[i] = true;
            seg_sum[i] = nums[i];
            if (i > 0 && active[i - 1]) unite(i, i - 1);
            if (i < n - 1 && active[i + 1]) unite(i, i + 1);
            cur_max = std::max(cur_max, seg_sum[find(find, i)]);
        }
        return ans;
    }
};

class Solution {
    public long[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        int[] parent = new int[n];
        for (int i = 0; i < n; ++i) parent[i] = i;
        long[] segSum = new long[n];
        boolean[] active = new boolean[n];
        long[] ans = new long[n];
        long curMax = 0;
        for (int q = n - 1; q >= 0; --q) {
            ans[q] = curMax;
            int i = removeQueries[q];
            active[i] = true;
            segSum[i] = nums[i];
            if (i > 0 && active[i - 1]) union(parent, segSum, i, i - 1);
            if (i < n - 1 && active[i + 1]) union(parent, segSum, i, i + 1);
            curMax = Math.max(curMax, segSum[find(parent, i)]);
        }
        return ans;
    }
    private int find(int[] parent, int i) {
        if (parent[i] != i) parent[i] = find(parent, parent[i]);
        return parent[i];
    }
    private void union(int[] parent, long[] segSum, int i, int j) {
        int ri = find(parent, i), rj = find(parent, j);
        if (ri != rj) {
            parent[ri] = rj;
            segSum[rj] += segSum[ri];
        }
    }
}

var maximumSegmentSum = function(nums, removeQueries) {
    const n = nums.length;
    const parent = new Int32Array(n);
    for (let i = 0; i < n; ++i) parent[i] = i;
    const segSum = new BigInt64Array(n);
    const active = new Uint8Array(n);
    function find(i) {
        if (parent[i] !== i) parent[i] = find(parent[i]);
        return parent[i];
    }
    function union(i, j) {
        const ri = find(i), rj = find(j);
        if (ri !== rj) {
            parent[ri] = rj;
            segSum[rj] += segSum[ri];
        }
    }
    const ans = new Array(n);
    let curMax = 0n;
    for (let q = n - 1; q >= 0; --q) {
        ans[q] = Number(curMax);
        const i = removeQueries[q];
        active[i] = 1;
        segSum[i] = BigInt(nums[i]);
        if (i > 0 && active[i - 1]) union(i, i - 1);
        if (i < n - 1 && active[i + 1]) union(i, i + 1);
        const rootVal = segSum[find(i)];
        if (rootVal > curMax) curMax = rootVal;
    }
    return ans;
};
